      hu: ["Kézművesség és ipar kombinációja.", "Helyi áruk gyártása.", "Ipari gyártás.", "Regionális gazdasági központ."],
      ro: ["Combinație de artizanat și industrie.", "Producția de bunuri locale.", "Producție industrială.", "Centru economic regional."],
